lib_dlb_fgets(char *buf, int len, dlb *dp)
{
    int i;
    char *bp, c = 0;
    if (len <= 0)
        return buf;
    if (dp->mark >= dp->size)
        return (char *) 0;
    len--;
    for (i = 0, bp = buf; i < len && dp->mark < dp->size && c != '\n';
         i++, bp++) {
        if (dlb_fread(bp, 1, 1, dp) <= 0)
            break;
        c = *bp;
    }
    *bp = '\0';
    return buf;
}
